package net.officefloor.hq.app.setting;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.TreeMap;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.Sheet;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** A sheet's settings: the role each user name has on it, and its clerk limit, its floor, its cap, its terms
 *  (and any grade's own terms) and its late percent, its policy date and its period numbering from. The
 *  settings that carry a figure are dated: each value recorded is in force from its from-date. A claim's
 *  floor, late percent and terms are those in force on its date; the clerk limit and the cap those in
 *  force on the sheet's today. */
@Service
public class SettingService {

    /** The key prefix of a grade's own terms: terms-A, terms-B, terms-C. */
    private static final String GRADE_TERMS = "terms-";

    private final SheetService sheets;
    private final SheetRepository sheetRepository;
    private final SheetRoleRepository roles;
    private final SettingValueRepository values;
    private final Audit audit;

    public SettingService(SheetService sheets, SheetRepository sheetRepository, SheetRoleRepository roles,
            SettingValueRepository values, Audit audit) {
        this.sheets = sheets;
        this.sheetRepository = sheetRepository;
        this.roles = roles;
        this.values = values;
        this.audit = audit;
    }

    /** The roles assigned on the sheet, by user name. */
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUserAsc(sheetId);
    }

    /** The user's role on the sheet: clerk unless assigned another. */
    public Role roleOf(String sheetId, String user) {
        return roles.findBySheetIdAndUser(sheetId, user).map(SheetRole::getRole).orElse(Role.CLERK);
    }

    /** The floor a sheet starts with: in force before the first from-date recorded for it. */
    public static final BigDecimal START_FLOOR = new BigDecimal("1.00");

    /** The late percent a sheet starts with. */
    public static final BigDecimal START_LATE_PCT = new BigDecimal("0.00");

    /** The terms a sheet starts with, in days. */
    public static final int START_TERMS = 14;

    /** The values recorded for the sheet's dated settings, by key, each list by from-date. */
    public Map<String, List<SettingValue>> dated(String sheetId) {
        Map<String, List<SettingValue>> byKey = new TreeMap<>();
        values.findBySheetIdOrderByKeyAscFromAsc(sheetId)
                .forEach(v -> byKey.computeIfAbsent(v.getKey(), k -> new ArrayList<>()).add(v));
        return byKey;
    }

    /** The value recorded for a dated setting that is in force on a date: the one with the latest
     *  from-date on or before it; empty before every from-date (the sheet's starting value applies). */
    private Optional<SettingValue> inForce(String sheetId, String key, LocalDate on) {
        return values.findFirstBySheetIdAndKeyAndFromLessThanEqualOrderByFromDesc(sheetId, key, on);
    }

    /** The sheet's clerk limit in force on its today; null when there is none. */
    public BigDecimal clerkLimit(String sheetId) {
        return inForce(sheetId, "clerk-limit", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
    }

    /** The sheet's floor in force on a date: the least the live due of a claim of that date can be. */
    public BigDecimal floor(String sheetId, LocalDate on) {
        return inForce(sheetId, "floor", on).map(SettingValue::getValue).orElse(START_FLOOR);
    }

    /** The sheet's cap in force on its today: the most a person's due-total can be; null when there is none. */
    public BigDecimal cap(String sheetId) {
        return inForce(sheetId, "cap", sheets.today(sheetId)).map(SettingValue::getValue).orElse(null);
    }

    /** A person's due-total held to the sheet's cap; a due-total of none (n/a) is not capped. */
    public BigDecimal capped(String sheetId, BigDecimal dueTotal) {
        BigDecimal cap = cap(sheetId);
        return dueTotal == null || cap == null ? dueTotal : dueTotal.min(cap);
    }

    /** The sheet's terms in days in force on a date: a claim of that date is due by its date plus them. */
    public int terms(String sheetId, LocalDate on) {
        return inForce(sheetId, "terms", on).map(v -> v.getValue().intValue()).orElse(START_TERMS);
    }

    /** The grades' own terms in force on a date, by grade; a grade not listed takes the sheet's terms. */
    public Map<String, Integer> gradeTerms(String sheetId, LocalDate on) {
        Map<String, Integer> byGrade = new LinkedHashMap<>();
        dated(sheetId).forEach((key, recorded) -> {
            if (!key.startsWith(GRADE_TERMS)) {
                return;
            }
            recorded.stream().filter(v -> !v.getFrom().isAfter(on)).reduce((a, b) -> b)
                    .ifPresent(v -> byGrade.put(key.substring(GRADE_TERMS.length()), v.getValue().intValue()));
        });
        return byGrade;
    }

    /** The terms in days a claim of the grade dated on a date takes: the grade's own in force then,
     *  else the sheet's. */
    public int termsFor(String sheetId, String grade, LocalDate on) {
        if (grade == null) {
            return terms(sheetId, on);
        }
        return inForce(sheetId, GRADE_TERMS + grade, on).map(v -> v.getValue().intValue())
                .orElseGet(() -> terms(sheetId, on));
    }

    /** The sheet's late percent in force on a date: an overdue claim of that date's due gains it of its
     *  figure for every full 30 days it is overdue. */
    public BigDecimal latePct(String sheetId, LocalDate on) {
        return inForce(sheetId, "late-pct", on).map(SettingValue::getValue).orElse(START_LATE_PCT);
    }

    /** The sheet's policy date as set; null when it is blank (the sheet's today applies). */
    public LocalDate policyDateSet(String sheetId) {
        return sheets.load(sheetId).getPolicyDate();
    }

    /** The sheet's policy date in force: as set, else the sheet's today. */
    public LocalDate policyDate(String sheetId) {
        LocalDate set = policyDateSet(sheetId);
        return set != null ? set : sheets.today(sheetId);
    }

    /** The sheet's period numbering from; null when it is blank (off). */
    public LocalDate periodNumberingFrom(String sheetId) {
        return sheets.load(sheetId).getPeriodNumberingFrom();
    }

    /** How a claim dated on the given date rounds: half up before the policy date, half to even on or
     *  after it. */
    public RoundingMode roundingOn(String sheetId, LocalDate date) {
        return date.isBefore(policyDate(sheetId)) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Assign a user name a role on the sheet. */
    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        sheets.lock(sheetId);
        SheetRole saved = roles.findBySheetIdAndUser(sheetId, user)
                .map(existing -> {
                    existing.setRole(role);
                    return existing;
                })
                .orElseGet(() -> new SheetRole(sheetId, user, role));
        saved = roles.saveAndFlush(saved);
        audit.recordOnCommit("ROLE_SET sheet=" + sheetId + " by=" + by + " user=" + user + " role=" + role.label());
        return saved;
    }

    /** Record the sheet's clerk limit from a date (null for the sheet's today); a null limit records none. */
    @Transactional
    public SettingValue setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        return record(sheetId, by, "clerk-limit", limit != null ? limit.setScale(2, RoundingMode.UNNECESSARY) : null, from);
    }

    /** Record the sheet's floor from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
        return record(sheetId, by, "floor", floor.setScale(2, RoundingMode.UNNECESSARY), from);
    }

    /** Record the sheet's cap from a date (null for the sheet's today); a null cap records none. */
    @Transactional
    public SettingValue setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
        return record(sheetId, by, "cap", cap != null ? cap.setScale(2, RoundingMode.UNNECESSARY) : null, from);
    }

    /** Record the sheet's terms from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setTerms(String sheetId, String by, int terms, LocalDate from) {
        return record(sheetId, by, "terms", BigDecimal.valueOf(terms), from);
    }

    /** Record a grade's own terms on the sheet from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setGradeTerms(String sheetId, String by, String grade, int terms, LocalDate from) {
        return record(sheetId, by, GRADE_TERMS + grade, BigDecimal.valueOf(terms), from);
    }

    /** Record the sheet's late percent from a date (null for the sheet's today). */
    @Transactional
    public SettingValue setLatePct(String sheetId, String by, BigDecimal latePct, LocalDate from) {
        return record(sheetId, by, "late-pct", latePct.setScale(2, RoundingMode.UNNECESSARY), from);
    }

    /** Record a dated setting's value from a date, the sheet's today when none is given, keeping the
     *  values already recorded; one already recorded from that date is replaced. */
    private SettingValue record(String sheetId, String by, String key, BigDecimal value, LocalDate from) {
        sheets.lock(sheetId);
        LocalDate on = from != null ? from : sheets.today(sheetId);
        SettingValue saved = values.findBySheetIdAndKeyAndFrom(sheetId, key, on)
                .map(existing -> {
                    existing.setValue(value);
                    return existing;
                })
                .orElseGet(() -> new SettingValue(sheetId, key, on, value));
        saved = values.saveAndFlush(saved);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=" + key + " value="
                + (value != null ? (key.startsWith("terms") ? String.valueOf(value.intValue()) : value.toPlainString()) : "")
                + (from != null ? " from=" + from : ""));
        return saved;
    }

    /** Change the sheet's policy date; null leaves it blank (the sheet's today). */
    @Transactional
    public Sheet setPolicyDate(String sheetId, String by, LocalDate policyDate) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPolicyDate(policyDate);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=policy-date value="
                + (policyDate != null ? policyDate.toString() : ""));
        return saved;
    }

    /** Change the sheet's period numbering from; null leaves it blank (off). */
    @Transactional
    public Sheet setPeriodNumberingFrom(String sheetId, String by, LocalDate from) {
        sheets.load(sheetId);
        Sheet sheet = sheetRepository.findLockedById(sheetId).orElseThrow();
        sheet.setPeriodNumberingFrom(from);
        Sheet saved = sheetRepository.saveAndFlush(sheet);
        audit.recordOnCommit("SETTING_CHANGED sheet=" + sheetId + " by=" + by + " key=period-numbering-from value="
                + (from != null ? from.toString() : ""));
        return saved;
    }
}
package net.officefloor.hq.app.setting;

import jakarta.validation.constraints.DecimalMin;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.Digits;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/settings")
public class SettingController {

    /** A user name's role as the screen shows it: clerk or steward. */
    public record RoleView(String user, String role) {
        static RoleView of(SheetRole role) {
            return new RoleView(role.getUser(), role.getRole().label());
        }
    }

    /** The sheet's settings: the roles assigned, and as in force on the sheet's today the clerk limit (two decimals; null for none) and
     *  the floor (two decimals), the cap (two decimals; null for none), the terms (whole days), the late percent (two decimals) and the policy
     *  date (blank for the sheet's today) and the period numbering from (blank for off), and the grades'
     *  own terms by grade (a grade not listed takes the sheet's terms); and every value recorded for the
     *  dated settings, by key (floor, late-pct, terms, terms-<grade>, clerk-limit, cap). */
    public record SettingsView(List<RoleView> roles, String clerkLimit, String floor, String cap, int terms, String latePct,
            String policyDate, String periodNumberingFrom, Map<String, Integer> gradeTerms,
            Map<String, List<DatedView>> dated) {
    }

    /** A value recorded for a dated setting, in force from its from-date: two decimals, whole days for
     *  terms, null for no clerk limit or cap. */
    public record DatedView(String from, String value) {
        static DatedView of(SettingValue v) {
            String value = v.getValue() == null ? null
                    : v.getKey().startsWith("terms") ? String.valueOf(v.getValue().intValue())
                    : v.getValue().toPlainString();
            return new DatedView(v.getFrom().toString(), value);
        }
    }

    /** A role for a user name: clerk or steward. */
    public record RoleRequest(@NotBlank @Size(max = 200) String user, @NotBlank String role) {
    }

    /** A clerk limit of 0.00 or more with up to two decimals; null removes the limit. */
    public record ClerkLimitRequest(@DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /** A floor of 0.00 or more with up to two decimals. */
    public record FloorRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /** A cap of 0.00 or more with up to two decimals; null removes the cap. */
    public record CapRequest(@DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /** Terms of 0 or more whole days. Each figure setting is recorded from its from-date; null for the
     *  sheet's today. */
    public record TermsRequest(@NotNull @Min(0) @Max(36500) Integer value, LocalDate from) {
    }

    /** A late percent of 0.00 or more with up to two decimals. */
    public record LatePctRequest(@NotNull @DecimalMin("0.00") @Digits(integer = 10, fraction = 2) BigDecimal value, LocalDate from) {
    }

    /** A policy date; null leaves it blank (the sheet's today). */
    public record PolicyDateRequest(LocalDate value) {
    }

    /** A period numbering from date; null leaves it blank (off). */
    public record PeriodNumberingFromRequest(LocalDate value) {
    }

    private final SettingService service;
    private final RollupService rollups;
    private final SheetService sheets;

    public SettingController(SettingService service, RollupService rollups, SheetService sheets) {
        this.service = service;
        this.rollups = rollups;
        this.sheets = sheets;
    }

    /** The sheet's settings. */
    @GetMapping
    public SettingsView get(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        String sheet = sheetId.trim();
        return view(sheet);
    }

    /** Assign a user name a role; a role other than clerk or steward is refused. */
    @PutMapping("/roles")
    public RoleView setRole(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated RoleRequest request) {
        Role role = Role.of(request.role().trim())
                .orElseThrow(() -> new IllegalArgumentException("No role " + request.role()));
        return RoleView.of(service.setRole(sheetId.trim(), SignedInUser.decode(user), request.user().trim(), role));
    }

    /** Change the sheet's clerk limit. */
    @PutMapping("/clerk-limit")
    public SettingsView setClerkLimit(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated ClerkLimitRequest request) {
        String sheet = sheetId.trim();
        service.setClerkLimit(sheet, SignedInUser.decode(user), request.value(), request.from());
        return view(sheet);
    }

    /** Change the sheet's floor; the figures it moves are followed in the audit. */
    @PutMapping("/floor")
    public SettingsView setFloor(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated FloorRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setFloor(sheet, by, request.value(), request.from()));
        return view(sheet);
    }

    /** Change the sheet's cap; the figures it moves are followed in the audit. */
    @PutMapping("/cap")
    public SettingsView setCap(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated CapRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setCap(sheet, by, request.value(), request.from()));
        return view(sheet);
    }

    /** Change the sheet's terms; the late charges it moves are followed in the audit. */
    @PutMapping("/terms")
    public SettingsView setTerms(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated TermsRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setTerms(sheet, by, request.value(), request.from()));
        return view(sheet);
    }

    /** Set a grade's (A, B or C) own terms; they fix the due-by of the grade's claims dated from their from-date that are added from now on. */
    @PutMapping("/terms/{grade}")
    public SettingsView setGradeTerms(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @PathVariable @Pattern(regexp = "[ABC]") String grade,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated TermsRequest request) {
        String sheet = sheetId.trim();
        service.setGradeTerms(sheet, SignedInUser.decode(user), grade, request.value(), request.from());
        return view(sheet);
    }

    /** Change the sheet's late percent; the figures it moves are followed in the audit. */
    @PutMapping("/late-pct")
    public SettingsView setLatePct(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated LatePctRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setLatePct(sheet, by, request.value(), request.from()));
        return view(sheet);
    }

    /** Change the sheet's policy date; the figures it moves are followed in the audit. */
    @PutMapping("/policy-date")
    public SettingsView setPolicyDate(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated PolicyDateRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        rollups.track(sheet, by, () -> service.setPolicyDate(sheet, by, request.value()));
        return view(sheet);
    }

    /** Change the sheet's period numbering from; it numbers only claims opened from then on. */
    @PutMapping("/period-numbering-from")
    public SettingsView setPeriodNumberingFrom(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user,
            @RequestBody @Validated PeriodNumberingFromRequest request) {
        String sheet = sheetId.trim();
        service.setPeriodNumberingFrom(sheet, SignedInUser.decode(user), request.value());
        return view(sheet);
    }

    private SettingsView view(String sheet) {
        LocalDate today = sheets.today(sheet);
        BigDecimal limit = service.clerkLimit(sheet);
        BigDecimal cap = service.cap(sheet);
        LocalDate policyDate = service.policyDateSet(sheet);
        LocalDate numberingFrom = service.periodNumberingFrom(sheet);
        Map<String, List<DatedView>> dated = new LinkedHashMap<>();
        service.dated(sheet).forEach((key, recorded) -> dated.put(key, recorded.stream().map(DatedView::of).toList()));
        return new SettingsView(service.roles(sheet).stream().map(RoleView::of).toList(),
                limit != null ? limit.toPlainString() : null, service.floor(sheet, today).toPlainString(),
                cap != null ? cap.toPlainString() : null, service.terms(sheet, today),
                service.latePct(sheet, today).toPlainString(), policyDate != null ? policyDate.toString() : "",
                numberingFrom != null ? numberingFrom.toString() : "", service.gradeTerms(sheet, today), dated);
    }

    /** A role that is not clerk or steward, or a limit that is not a number, is refused. */
    @ExceptionHandler({IllegalArgumentException.class, HttpMessageNotReadableException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** The user name's role was first set concurrently; caught by the unique index. */
    @ExceptionHandler(DataIntegrityViolationException.class)
    @ResponseStatus(HttpStatus.CONFLICT)
    public void conflict() {
    }
}
package net.officefloor.hq.app.sheet;

import java.time.Clock;
import java.time.LocalDate;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Loads sheets by id; a sheet never loaded before starts empty, its today the real date. */
@Service
public class SheetService {

    private final SheetRepository sheets;
    private final Clock clock;

    public SheetService(SheetRepository sheets, Clock clock) {
        this.sheets = sheets;
        this.clock = clock;
    }

    /** The sheet with this id, created empty when it was never loaded before. */
    public Sheet load(String id) {
        return sheets.findById(id).orElseGet(() -> {
            try {
                return sheets.saveAndFlush(new Sheet(id, LocalDate.now(clock)));
            } catch (DataIntegrityViolationException e) {
                return sheets.findById(id).orElseThrow(() -> e); // created concurrently
            }
        });
    }

    /** The sheet's today: the date every date-dependent decision and default on the sheet uses. */
    public LocalDate today(String id) {
        return load(id).getToday();
    }

    /** Take the sheet's next claim number, holding the sheet locked until the transaction ends so
     *  claims opened at the same moment get different numbers. */
    @Transactional
    public long nextClaimNumber(String id) {
        load(id);
        Sheet sheet = sheets.findLockedById(id).orElseThrow();
        long number = sheet.nextClaimNumber();
        sheets.saveAndFlush(sheet);
        return number;
    }

    /** Hold the sheet locked until the transaction ends, so changes to it made at the same moment
     *  wait their turn. */
    @Transactional
    public void lock(String id) {
        load(id);
        sheets.findLockedById(id).orElseThrow();
    }

    /** Change the sheet's today. */
    @Transactional
    public Sheet setToday(String id, LocalDate today) {
        Sheet sheet = load(id);
        sheet.setToday(today);
        return sheets.save(sheet);
    }
}
