111	    /** Move a claim to a new status; a change its status does not allow is refused, as is the user
112	     *  who opened a claim settling it. A clerk settling a claim whose due is above the clerk limit
113	     *  leaves it PENDING a steward's approval instead. */
114	    @Transactional
115	    public Claim changeStatus(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
116	        Person person = person(sheetId, personId);
117	        // Lock the sheet first, so a claim opened at the same moment elsewhere waits and the claim
118	        // read below is its latest state.
119	        if (to == ClaimStatus.OPEN) {
120	            sheets.lock(sheetId);
121	        }
122	        Claim claim = claim(sheetId, personId, id);
123	        refuseClosed(sheetId, claim.getDate());
124	        if (!claim.getStatus().canMoveTo(to)) {
125	            throw new StatusChangeRefusedException(claim.getStatus(), to);
126	        }
127	        if (to == ClaimStatus.SETTLED && user.equals(claim.getOpenedBy())) {
128	            throw new OwnClaimSettleRefusedException(user);
129	        }
130	        if (to == ClaimStatus.SETTLED && claim.deferredOn(sheets.today(sheetId))) {
131	            throw new StatusChangeRefusedException(claim.getStatus(), to);
132	        }
133	        // Taken while the claim is still OPEN, so a settled due freezes in the late charge it has
134	        // gathered by then.
135	        BigDecimal due = to == ClaimStatus.SETTLED ? dueOf(sheetId, person, claim) : null;
136	        if (to == ClaimStatus.SETTLED && overClerkLimit(sheetId, user, due)) {
137	            to = ClaimStatus.PENDING;
138	        }
139	        claim.setStatus(to);
140	        if (to == ClaimStatus.OPEN) {
141	            claim.setNumber(nextNumber(sheetId, claim.getDate()));
142	            claim.setOpenedBy(user);
143	        } else if (to == ClaimStatus.SETTLED) {
144	            claim.setSettledDue(due);
145	        }
146	        Claim saved = claims.saveAndFlush(claim);
147	        log(sheetId, user, person, saved);
148	        String event = switch (to) {
149	            case OPEN -> "CLAIM_OPENED";
150	            case PENDING -> "CLAIM_PENDING";
151	            case SETTLED -> "CLAIM_SETTLED";
152	            case VOID -> "CLAIM_VOIDED";
153	            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
154	        };
155	        String line = line(event, sheetId, user, person, saved, saved.getNumber());
156	        if (to == ClaimStatus.SETTLED) {
157	            line += " due=" + settledDueText(saved);
158	        }
159	        audit.recordOnCommit(line);
160	        return saved;
161	    }
