169	        Claim claim = claim(sheetId, personId, id);
170	        refuseClosed(sheetId, claim.getDate());
171	        if (claim.getStatus() != ClaimStatus.OPEN) {
172	            throw new DeferRefusedException("A " + claim.getStatus() + " claim cannot be deferred");
173	        }
