184	    /** A steward approves a PENDING claim: it is SETTLED, its due frozen at this moment. Anyone else,
185	     *  the user who opened it, or a claim that is not PENDING, is refused. */
186	    @Transactional
187	    public Claim approve(String sheetId, String user, Long personId, Long id) {
