217	    /** A steward re-settles a SETTLED claim: its settled due is frozen again at the figure it would
218	     *  have today as an OPEN claim bound by no statement (today's rates, grades, floor and late
219	     *  charge), and its status log gains a SETTLED line. Anyone else, a claim that is not SETTLED, or
220	     *  one dated in a closed period, is refused. */
221	    @Transactional
222	    public Claim resettle(String sheetId, String user, Long personId, Long id) {
223	        Person person = person(sheetId, personId);
224	        Claim claim = claim(sheetId, personId, id);
225	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
226	            throw new ResettleRefusedException(user);
227	        }
228	        if (claim.getStatus() != ClaimStatus.SETTLED) {
229	            throw new StatusChangeRefusedException(claim.getStatus(), ClaimStatus.SETTLED);
230	        }
231	        refuseClosed(sheetId, claim.getDate());
232	        String old = settledDueText(claim);
233	        BigDecimal figure = liveFigureOf(sheetId, person, claim);
234	        claim.setSettledDue(figure == null ? null : figure.add(lateChargeOf(sheetId, claim, figure, true)));
235	        Claim saved = claims.saveAndFlush(claim);
236	        log(sheetId, user, person, saved);
237	        audit.recordOnCommit(line("CLAIM_RESETTLED", sheetId, user, person, saved, saved.getNumber())
