242	    /** A steward moves a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
243	     *  number and date, loses any figure a statement bound it to (live again until its new person's
244	     *  next statement), and is listed as its new person's newest claim. Anyone else, a SETTLED or VOID
245	     *  claim, a correction (it names a claim of its own person), a claim dated in a closed period, or
246	     *  a move to the same person or to one retired before the claim's date, is refused. */
247	    @Transactional
248	    public Claim reassign(String sheetId, String user, Long personId, Long id, Long toPersonId) {
249	        Person from = person(sheetId, personId);
250	        Person to = person(sheetId, toPersonId);
251	        Claim claim = claim(sheetId, personId, id);
252	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
253	            throw new ReassignRefusedException(user);
254	        }
255	        if (!claim.getStatus().canReassign()) {
256	            throw new MoveRefusedException("A " + claim.getStatus() + " claim cannot move to another person");
257	        }
258	        if (from.getId().equals(to.getId())) {
259	            throw new MoveRefusedException("The claim is already " + to.getName() + "'s");
260	        }
261	        if (claim.isCorrection()) {
262	            throw new MoveRefusedException("A correction stays with the person whose claim it corrects");
263	        }
264	        refuseClosed(sheetId, claim.getDate());
265	        refuseRetired(to, claim.getDate());
266	        claim.setPersonId(to.getId());
267	        claim.unbind();
268	        claims.saveAndFlush(claim);
269	        claims.relist(claim.getId());
270	        Claim saved = claim(sheetId, to.getId(), id);
271	        audit.recordOnCommit(line("CLAIM_REASSIGNED", sheetId, user, to, saved, saved.getNumber())
272	                + " from=" + from.getName() + " to=" + to.getName());
273	        return saved;
274	    }
