295	    /** The PENDING claim a steward approves or rejects; refused when it is not PENDING, dated in a
296	     *  closed period, or the user is not a steward. */
297	    private Claim pending(String sheetId, String user, Long personId, Long id, ClaimStatus to) {
298	        Claim claim = claim(sheetId, personId, id);
299	        refuseClosed(sheetId, claim.getDate());
300	        if (claim.getStatus() != ClaimStatus.PENDING) {
301	            throw new StatusChangeRefusedException(claim.getStatus(), to);
302	        }
303	        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
304	            throw new ApprovalRefusedException(user);
305	        }
306	        return claim;
307	    }
