721	/** Where a claim is in its life: DRAFT, then OPEN, then SETTLED; an OPEN claim a clerk settles above
722	 *  the clerk limit is PENDING until a steward approves it (SETTLED) or rejects it (OPEN again); a
723	 *  DRAFT, OPEN or PENDING claim can be VOID. */
724	public enum ClaimStatus {
725	    DRAFT, OPEN, PENDING, SETTLED, VOID;
726	
727	    /** Whether the claim counts toward what is claimed and due. */
728	    public boolean counts() {
729	        return this == OPEN || this == PENDING || this == SETTLED;
730	    }
731	
732	    /** Whether the claim is open: OPEN, or PENDING an approval. */
733	    public boolean isOpen() {
734	        return this == OPEN || this == PENDING;
735	    }
736	
737	    /** Whether a claim in this status may be moved to another person: a SETTLED or VOID one cannot. */
738	    public boolean canReassign() {
739	        return this == DRAFT || this == OPEN || this == PENDING;
740	    }
741	
742	    /** Whether a claim in this status may be opened, settled or voided to the given one; a PENDING
743	     *  claim leaves PENDING only by being approved, rejected or voided. */
744	    public boolean canMoveTo(ClaimStatus next) {
745	        return switch (next) {
746	            case OPEN -> this == DRAFT;
747	            case SETTLED -> this == OPEN;
748	            case VOID -> this == DRAFT || this == OPEN || this == PENDING;
749	            case PENDING, DRAFT -> false;
750	        };
751	    }
752	}
