785	                .filter(claim -> ids.contains(claim.getId()))
786	                .sorted(Comparator.comparing((Claim claim) -> personOrder.getOrDefault(claim.getPersonId(), Integer.MAX_VALUE)))
787	                .toList();
788	    }
